// lib/numerology-life-path-pair-catalog-zh.ts
var PLATEAU_SET = new Set(LIFE_PATH_PLATEAU_NUMBERS);
function assertPlateau(n, label) {
  if (!PLATEAU_SET.has(n)) {
    throw new Error(`${label}=${n} \u975E\u672C\u7AD9\u4E3B\u8DEF\u5F84\u76D8\u9762\uFF08\u4EC5 ${LIFE_PATH_PLATEAU_NUMBERS.join("\u3001")}\uFF09`);
  }
}
var ALL_LIFE_PATH_ORDERED_PAIRS_144 = (() => {
  const out = [];
  for (const me of LIFE_PATH_PLATEAU_NUMBERS) {
    for (const other of LIFE_PATH_PLATEAU_NUMBERS) {
      out.push([me, other]);
    }
  }
  return out;
})();
function lifePathPairCatalogBodyZh(me, other) {
  assertPlateau(me, "me");
  assertPlateau(other, "other");
  if (me === other) return lifePathPairTwinManualBodyZh(me);
  const body = lifePathPairMatrixWorkspaceBodyZh(me, other);
  if (!body) throw new Error(`pair matrix missing for ${me}-${other}`);
  return body;
}

// lib/numerology-life-path-pair-matrix-enumerate-zh.ts
function allPairMatrixDualDraftsZh() {
  return lifePathPairMatrixKeysZh().map((k) => {
    const [lo, hi] = k.split("-").map(Number);
    const hiLoKey = `${hi}-${lo}`;
    return {
      lo,
      hi,
      keyLoHi: k,
      bodyWhenMeIsLo: PAIR_MATRIX_MANUAL_ZH4[k],
      bodyWhenMeIsHi: PAIR_MATRIX_MANUAL_ZH_HI_FIRST[hiLoKey]
    };
  });
}
function formatPairMatrixBodyMarkdownZh(body, heading) {
  const h = heading ? `### ${heading}

` : "";
  const [a0, a1] = body.afterLead;
  const bl = body.bullets.map((b) => `- ${b}`).join("\n");
  return `${h}${body.lead}

${a0}

${a1}

${bl}
`;
}

